import type { ChangeEvent } from "react";
type Props = { value: string; onValueChange: (value: string) => void };
export function SearchInput({ value, onValueChange }: Props) {
  function handleChange(event: ChangeEvent<HTMLInputElement>): void { onValueChange(event.currentTarget.value); }
  return <input aria-label="Szukaj" value={value} onChange={handleChange} />;
}

