type TicketPreview = { id: number; title: string; assignee: string | null };
type TicketTableProps = { tickets: TicketPreview[]; selectedId: number | null; onSelect: (id: number) => void };
export function TicketTable({ tickets, selectedId, onSelect }: TicketTableProps) {
  return <table><thead><tr><th>ID</th><th>Tytuł</th><th>Osoba</th><th>Akcje</th></tr></thead><tbody>
    {tickets.map(ticket => <tr key={ticket.id} className={selectedId === ticket.id ? "row--selected" : "row"}>
      <td>{ticket.id}</td><td>{ticket.title}</td><td>{ticket.assignee ?? "—"}</td>
      <td><button type="button" onClick={() => onSelect(ticket.id)}>Wybierz #{ticket.id}</button></td>
    </tr>)}
  </tbody></table>;
}
const sample = <TicketTable tickets={[{ id: 1, title: "API", assignee: null }, { id: 2, title: "Login", assignee: "anna" }]} selectedId={2} onSelect={id => console.log(id)} />;

